const itemsOf=cid=>coll('regCertItems').filter(x=>x.cycle===cid);
const itemStatus=it=>it.status==='Signed'?'Signed':it.obls.some(o=>o.ans)?'In progress':'Not started';
const itemLate=it=>{const c=cyc(it.cycle);return !!c&&c.status!=='Draft'&&it.status!=='Signed'&&c.due<TODAY};
const itemK=it=>it.status==='Signed'?'green':itemLate(it)?'red':itemStatus(it)==='In progress'?'amber':'blue';
const itemTxt=it=>it.status==='Signed'?(it.signed&&it.signed.late?'Signed late':'Signed'):itemLate(it)?'⚠ Late':itemStatus(it);
