 const dl=breachDeadline(b);if(!dl)return{state:'tbc',text:'Clock not set: enter hours or days after confirming with Legal',k:'amber'};
 const dlt=fmtDT(msDate(dl)+' '+new Date(dl).toTimeString().slice(0,5)).replace(/ (\d\d:\d\d)$/,' $1');
 if(b.sentAt){const late=Date.parse(b.sentAt)>dl;return{state:late?'late':'met',text:late?`Notified ${fmtDT(b.sentAt)}, ${dur(Date.parse(b.sentAt)-dl)} after the deadline (${dlt})`:`Notified ${fmtDT(b.sentAt)}, within the clock (deadline ${dlt})`,k:late?'red':'green'}}
