// ================================================================ 10. traceability and coverage
function traceData(){
 const s=S(),cs=s.controls||[],pols=s.policies||[],tests=s.tests||[],issues=s.issues||[],out=[];
 obls().filter(o=>o.status!=='Not applicable').forEach(o=>{
  const ctl=(o.controls||[]).filter(id=>cs.some(c=>c.id===id)),pol=pols.filter(p=>(p.ctrls||[]).some(c=>ctl.includes(c))).map(p=>p.id),ts=tests.filter(t=>ctl.includes(t.ctrl)).sort((a,b)=>a.date<b.date?1:-1),last=ts[0]||null;
  const docs=[...new Set([o.id,...ctl,...pol].flatMap(id=>D.docsFor(id).map(d=>d.id)))],ev=(o.evidence?1:0)+docs.length;
  const tIds=new Set(ts.map(t=>t.id)),oi=issues.filter(i=>i.status!=='Closed'&&(i.link===o.id||ctl.includes(i.link)||tIds.has(i.link)));
  const gaps=[];if(!ctl.length)gaps.push('No control');if(!pol.length)gaps.push('No policy');if(!last||last.result==='Not tested')gaps.push('Control not tested');else if(last.result==='Ineffective')gaps.push('Control ineffective');if(!ev)gaps.push('No evidence');if(oi.length)gaps.push('Open issues');
  out.push({o,ctl,pol,last,ev,oi,gaps,traced:!!ctl.length&&!!pol.length&&!!last&&last.result!=='Not tested'&&ev>0,jurs:oblJurs(o),fw:fwCode(o.fw)})});
 return out}
const GAPK=['No control','No policy','Control not tested','Control ineffective','No evidence','Open issues'];
const pctOf=(a,b)=>b?Math.round(a/b*100):0;
