 panel('regtrace','matrix').innerHTML=kp+toolbar('regtrace','m','Search obligations, owners…',[['fw',['All',...fws],'All frameworks'],['g',['All','Fully traced',...GAPK],'All gap types']])+card('Obligation to policy to control to test to evidence',`${shown.length} of ${rows.length} shown. Policies are found through the controls they list; evidence counts the evidence reference plus Documents linked to the obligation, control or policy.`,table(['Obligation','Policy','Control','Latest control test','Evidence','Open issues','Gaps'],shown.map(r=>`<tr data-op="open" data-t="obligation" data-id="${r.o.id}"><td style="white-space:normal"><div class="riskname">${E(r.o.id)} · ${E(clip(r.o.title,70))}</div><div class="riskarea">${E(r.fw)} ${E(r.o.ref)}</div></td><td>${r.pol.length?E(r.pol.join(', ')):'<span class="badgepill pill-red">none</span>'}</td><td>${r.ctl.length?E(r.ctl.join(', ')):'<span class="badgepill pill-red">none</span>'}</td><td>${r.last?`${pill(r.last.result,r.last.result==='Effective'?'green':r.last.result==='Ineffective'?'red':'amber')}<div class="riskarea">${E(r.last.id)} · ${fmt(r.last.date)}</div>`:'<span class="badgepill pill-amber">no test</span>'}</td><td>${r.ev}</td><td>${r.oi.length?`<span class="badgepill pill-red">${r.oi.length} open</span>`:'0'}</td><td style="white-space:normal">${r.traced?pill('✓ Fully traced','green'):r.gaps.map(g=>pill(g,'amber')).join(' ')}</td></tr>`),'No obligations. Adopt a framework in Standards & data first.'));
