G.linkers.push(id=>{let m,x;id=String(id||'');
 if(/^CAL-\d+$/.test(id)&&(x=coll('regCal').find(c=>c.id===id)))return{type:'cal',label:`${id} · ${x.title}`};
 if(/^FIL-\d+$/.test(id)&&(x=defOf(id)))return{type:'filing',label:`${id} · ${x.name}`};
 if(/^FRN-\d+$/.test(id)&&(x=coll('regFilingRuns').find(c=>c.id===id)))return{type:'filrun',label:`${id} · ${(defOf(x.def)||{}).name||x.def} ${x.period}`};
 if((m=/^(INS-\d+)(?:-([RFM])\d+)?$/.exec(id))&&(x=insp(m[1]))){const sub=m[2]?(x[{R:'requests',F:'findings',M:'milestones'}[m[2]]]||[]).find(q=>q.id===id):null;return{type:'insp',id:m[1],label:`${id} · ${sub?clip(sub.text,50):x.regulator+' '+x.type}`}}
 if(/^CRT-\d+$/.test(id)&&(x=cyc(id)))return{type:'cert',label:`${id} · ${x.name}`};
 if((m=/^(CRI-\d+)(?:-OB-\d+)?$/.exec(id))&&(x=item(m[1])))return{type:'crtitem',id:m[1],label:`${id} · certification ${x.certifier}`};
 if(/^BRC-\d+$/.test(id)&&(x=brc(id)))return{type:'breach',label:`${id} · ${x.title}`};
 if(/^COR-\d+$/.test(id)&&(x=corr(id)))return{type:'corr',label:`${id} · ${x.subject}`};
 if((m=/^(TST-\d+)(?:-R\d+)?$/.exec(id))&&(x=rtest(m[1])))return{type:'rtest',id:m[1],label:`${id} · test of ${x.ob}`};
 return null});
