 'rg-doc-pick':b=>{if(!canWrite())return;const ds=Object.assign({},b.dataset),cur=tgtList(ds)||[];openForm('Attach a document',[{name:'doc',label:'Existing document (Documents library)',type:'select',full:true,options:[['','— choose one, or create a note below —'],...docOpts(false).filter(o=>!cur.includes(o[0]))]},{name:'title',label:'Or create a new text note: title',full:true},{name:'text',label:'Note text',type:'textarea',full:true}],'Attach',x=>{
  if(x.doc){wrapErr(attachDoc(ds,x.doc).then(()=>toast('Document attached.')));return}
  if(x.title&&x.text){wrapErr(createAndAttach(ds,{title:x.title},{text:x.text,name:x.title.replace(/[^\w ]/g,'')+'.txt'}).then(d=>toast(`${d.id} created and attached.`)));return}
  return 'Choose a document, or give a title and text for a new note.'})},
 'rg-doc-detach':b=>{if(!canWrite())return;const ds=Object.assign({},b.dataset),l=tgtList(ds);if(!l)return;const i=l.indexOf(ds.doc);if(i<0)return;l.splice(i,1);try{D.unlink(ds.doc,ds.sub?ds.sid:ds.id)}catch(e){}logIt(ds.sid||ds.id,`Document ${ds.doc} detached.`);commit()},
